tool_calls:
awk '
function trim(s) { sub(/^[[:space:]]+/, "", s); sub(/[[:space:]]+$/, "", s); return s }
/^[[:space:]]*([;#]|$)/ { next }
/^[[:space:]]*\[/ {
    section = $0
    sub(/^[[:space:]]*\[/, "", section)
    sub(/\][[:space:]]*$/, "", section)
    if (!(section in seen_section)) { seen_section[section] = 1; sections[++section_count] = section }
    next
}
index($0, "=") {
    pos = index($0, "=")
    key = trim(substr($0, 1, pos - 1))
    id = section SUBSEP key
    if (!(id in values)) { keys[section, ++key_count[section]] = key }
    values[id] = substr($0, pos + 1)
}
END {
    for (s = 1; s <= section_count; s++) {
        section = sections[s]
        if (s > 1) print ""
        print "[" section "]"
        for (k = 1; k <= key_count[section]; k++) {
            key = keys[section, k]
            print key "=" values[section, key]
        }
    }
}' /config/defaults.ini /config/custom.ini > /config/merged.ini && cat /config/merged.ini

